        (j.named ? j.named.has(path) : j.spec.scanMatchers.some((re) => re.test(path))) &&
        !excluded(path, j.spec.excludeMatchers));
      if (!subs.length) continue;
      const text = ctx.read(path);
      if (text !== null) visit(ctx, subs, path, text);
