1	import { spawnSync } from 'node:child_process';
2	import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
3	import { join, resolve, sep } from 'node:path';
4	import { parseEntries } from './session-transcript.mjs';
5	import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
6	
7	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
8	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
9	  if (r.status !== 0 && !allowFail) {
10	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
11	  }
12	  return r.status === 0 ? r.stdout : null;
13	}
14	
15	const git = (root, ...args) => sh(root, 'git', args);
16	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
17	
18	// The base branch this repo's work is judged against, in preference order.
19	// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
20	// refs before a context is built at all — one list, so what CI fetches and what a
21	// context resolves can never name different branches.
22	export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];
23	
24	function resolveBaseRef(root) {
25	  for (const ref of BASE_REF_CANDIDATES) {
26	    if (gitTry(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) !== null) return ref;
27	  }
28	  return null;
29	}
30	
31	const FETCH_TIMEOUT_MS = 8000;
32	const FETCH_WINDOW_MS = 5 * 60_000;
33	
34	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
35	// clone freezes it at container-creation time — so every commit the base branch gained
36	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
37	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
38	// rule) report other people's commits as introduced by this change, and `--changed`
39	// widens to files the change never touched. Refreshing the ref once per run is what makes
40	// "the work" mean the work.
41	//
42	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
43	// fetch fails or times out and the run continues against the ref as it stands, exactly as
44	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
45	// no local branch, no index, no working tree, nothing the session could be surprised by.
46	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
47	//
48	// And it runs once per freshness window, not once per run: the Stop hook builds a context
49	// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
50	// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
51	// which ref was refreshed and when; a run inside the window trusts it and skips. The
52	// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
53	// nothing about this base's freshness — and the staleness the window admits is the same
54	// class the fetch's own failure tolerance already accepts, now bounded by the window.
55	function refreshBaseRef(root, ref) {
56	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
57	  const m = /^([^/]+)\/(.+)$/.exec(ref);
58	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
59	  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
60	  const marker = markerRel ? resolve(root, markerRel) : null;
61	  if (marker) {
62	    try {
63	      const last = JSON.parse(readFileSync(marker, 'utf8'));
64	      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
65	    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
66	  }
67	  const [, remote, branch] = m;
68	  const fetched = sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
69	    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
70	  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
71	  if (fetched !== null && marker) {
72	    try { writeFileSync(marker, JSON.stringify({ ref, at: Date.now() })); }
73	    catch { /* an unwritable git dir only costs the next run a fetch */ }
74	  }
75	}
76	
77	function lines(out) {
78	  return (out || '').split('\n').filter(Boolean);
79	}
80	
81	// Files git marks vendored or generated (linguist-vendored / linguist-generated in
82	// .gitattributes) — third-party or machine-written content, not the project's own
83	// code. `buildContext` drops these from the default `ctx.files`, so every check that
84	// reasons about "the project's code" skips them for free: a suppression marker inside
85	// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
86	// link in a vendored doc are none of them the project's decision. `git check-attr`
87	// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
88	// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
89	// check that reasons *about* generated files (generated-merge-driver).
90	function vendoredSet(root, files) {
91	  const set = new Set();
92	  if (!files.length) return set;
93	  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
94	    { allowFail: true, input: files.join('\n') + '\n' });
95	  for (const line of (out || '').split('\n')) {
96	    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
97	    if (m && m[2] === 'set') set.add(m[1]);
98	  }
99	  return set;
100	}
101	
102	// The complete set of top-level settings .claudinite-checks.json may carry. A key
103	// outside this set is a typo or a stale name — a settings error as real as invalid
104	// JSON, caught at load so it can't silently change nothing. `packConfig` is the
105	// legacy home of per-pack parameters — still honored while the fleet migrates to
106	// pack-entry `config` (the converge folds it in), no longer documented. The
107	// `pack-entry-config` baseline migration (engine/migrations/) documents the fold; when
108	// the fleet is off the old shape, drop the key here (and the overlay below) so
109	// a straggler gets the unknown-setting error.
110	// `claudinite` is the vendored-mount stamp — { updated: "<ISO datetime>", ref: "<sha>" },
111	// written by the nightly update pass, selecting which migration notes still apply
112	// (vendoring/DESIGN.md owns the model); the checks engine itself only tolerates it.
113	// `taskScheduler` is the per-repo maintenance anchor the vendored hourly scheduler
114	// reads (per-project-scheduling DESIGN §2) — { dailyHour, weeklyDay, monthlyDay },
